import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        t_str = next(iterator)
        T = int(t_str)
    except StopIteration:
        return

    results = []

    for _ in range(T):
        try:
            x_str = next(iterator)
            y_str = next(iterator)
            X = int(x_str)
            Y = int(y_str)
        except StopIteration:
            break

        diff = Y - X

        if diff == 0:
            results.append(0)
            continue

        if diff > 0:
            if diff % 2 != 0:
                results.append(1)
            else:
                results.append(2)
        else:
            diff_abs = -diff
            if diff_abs % 2 != 0:
                results.append(2)
            else:
                results.append(1)

    print('\n'.join(map(str, results)))

if __name__ == '__main__':
    solve()
